<?php
$portalModule='loginlog';require __DIR__.'/module-page.php';
$db=siteDatabaseConnection();
$results=['success'=>'Geslaagd','bad_password'=>'Naam/wachtwoord onjuist','mfa_required'=>'Wachtwoord goed, wacht op 2FA','bad_mfa'=>'2FA-code onjuist of verlopen','rate_limited'=>'Te veel pogingen','error'=>'Technische fout'];
$result=$_GET['result']??'';$search=$_GET['search']??'';$page=filter_var($_GET['page']??1,FILTER_VALIDATE_INT);
if(!is_string($result)||($result!==''&&!isset($results[$result]))||!is_string($search)||strlen($search)>133||!$page||$page<1||$page>10000){http_response_code(400);exit('Ongeldig filter.');}
$from=$_GET['from']??date('Y-m-d',strtotime('-30 days'));$until=$_GET['until']??date('Y-m-d');
foreach([$from,$until] as $value){$date=is_string($value)?DateTimeImmutable::createFromFormat('!Y-m-d',$value):false;if(!$date||$date->format('Y-m-d')!==$value){http_response_code(400);exit('Ongeldige datum.');}}
if($from>$until){http_response_code(400);exit('De vanafdatum ligt na de einddatum.');}
$start=$from.' 00:00:00';$end=(new DateTimeImmutable($until))->modify('+1 day')->format('Y-m-d 00:00:00');$pattern='%'.$search.'%';$offset=($page-1)*50;
$st=$db->prepare("SELECT username,ip_address,result,method,portal,created_at FROM portal_login_log WHERE created_at>=? AND created_at<? AND (?='' OR result=?) AND (?='' OR username LIKE ? OR ip_address LIKE ?) ORDER BY id DESC LIMIT 51 OFFSET ?");
$st->bind_param('sssssssi',$start,$end,$result,$result,$search,$pattern,$pattern,$offset);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$more=count($rows)>50;$rows=array_slice($rows,0,50);
function loginLogUrl($page){$query=$_GET;$query['page']=$page;return '/admin/loginlog.php?'.http_build_query($query);}
echo portalDocument('Inlogpogingen');
?><main><h1>Inlogpogingen</h1><p>Geslaagde en mislukte aanmeldingen via de gedeelde login. Deze historie begint bij de invoering van dit overzicht en wordt 30 dagen bewaard. Wachtwoorden en verificatiecodes worden nooit opgeslagen.</p><form method="get" class="login-log-filters"><label>Vanaf <input type="date" name="from" value="<?= portalEscape($from) ?>" required></label><label>Tot en met <input type="date" name="until" value="<?= portalEscape($until) ?>" required></label><label>Resultaat <select name="result"><option value="">Alle resultaten</option><?php foreach($results as $key=>$label): ?><option value="<?= $key ?>" <?= $result===$key?'selected':'' ?>><?= portalEscape($label) ?></option><?php endforeach ?></select></label><label>Gebruikersnaam of IP-adres <input name="search" value="<?= portalEscape($search) ?>" maxlength="133"></label><button>Filteren</button><a href="/admin/loginlog.php">Filters wissen</a></form><div class="login-log-table"><table><thead><tr><th>Datum en tijd</th><th>Gebruikersnaam</th><th>IP-adres</th><th>Resultaat</th><th>Methode</th><th>Portaal</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= portalEscape(date('d-m-Y H:i:s',strtotime($row['created_at']))) ?></td><td><?= portalEscape($row['username']?:'—') ?></td><td><?= portalEscape($row['ip_address']?:'—') ?></td><td><?= portalEscape($results[$row['result']]) ?></td><td><?= $row['method']==='mfa'?'Tweestapsverificatie':'Wachtwoord' ?></td><td><?= portalEscape(ucfirst($row['portal'])) ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="6">Geen inlogpogingen gevonden.</td></tr><?php endif ?></tbody></table></div><nav aria-label="Pagina’s inloghistorie"><?php if($page>1): ?><a href="<?= portalEscape(loginLogUrl($page-1)) ?>">Vorige</a><?php endif ?><?php if($more): ?> <a href="<?= portalEscape(loginLogUrl($page+1)) ?>">Volgende</a><?php endif ?></nav></main></body></html>
